package com.aistock.gateway.adminmarket;
import com.aistock.common.*;import com.aistock.common.marketrefs.MarketReferenceRecords.*;import com.aistock.gateway.*;import com.aistock.gateway.security.AdminReadAccess;import com.aistock.gateway.statistics.StatisticsIdentityClient;import com.fasterxml.jackson.databind.*;import jakarta.servlet.http.Cookie;import java.time.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.http.*;import org.springframework.test.web.servlet.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketReferenceProxyTest {
 final String V="11111111-1111-1111-1111-111111111111",path="/api/v1/admin/market-data/SH600030/versions/"+V+"/references",origin="http://127.0.0.1:15173";MarketReferencePublicClient client;StatisticsIdentityClient identity;MockMvc mvc;ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 @BeforeEach void init()throws Exception{client=mock(MarketReferencePublicClient.class);identity=mock(StatisticsIdentityClient.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"ADMIN",1),"t"));var now=Instant.parse("2026-10-28T00:00:00Z");var owners=List.of("prediction","scheduler","notification").stream().map(o->new OwnerResult(o,V,now,"COMPLETE",null,List.of(new Group("rows","记录","COMPLETE","0",null)))).toList();when(client.inspect(anyString(),anyString(),anyMap())).thenReturn(ResponseEntity.ok(mapper.writeValueAsBytes(ApiResponse.success(new Report("SH600030",V,"baostock","RAW","AVAILABLE",true,now,now,"COMPLETE",owners),"t"))));mvc=MockMvcBuilders.standaloneSetup(new MarketReferenceProxyController(client,new AdminReadAccess(identity,"test"),mapper)).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminMarketDataCorsConfiguration().adminMarketDataCors(origin).getFilter()).build();}
 @Test void explicitReadRoutesOnlyToMarketAndKeepsNoStore()throws Exception{mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a"))).andExpect(status().isOk()).andExpect(jsonPath("$.data.owners.length()").value(3)).andExpect(header().string("Cache-Control","no-store"));verify(client).inspect(eq("SH600030"),eq(V),argThat(h->!h.containsKey("X-Service-Token")));}
 @Test void authenticationAndBadReadBoundariesAreEnforced()throws Exception{mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a")).param("size","2")).andExpect(status().isBadRequest());mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a")).content("{}")).andExpect(status().isBadRequest());when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new StatisticsIdentityClient.Identity(UUID.randomUUID(),"USER",1),"t"));mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","u"))).andExpect(status().isForbidden());verifyNoInteractions(client);}
 @Test void invalidResponseNotExposedAndPreflightDoesNotCallIdentity()throws Exception{mvc.perform(options(path).header("Origin",origin).header("Access-Control-Request-Method","GET")).andExpect(status().isOk());verifyNoInteractions(identity,client);when(client.inspect(anyString(),anyString(),anyMap())).thenReturn(ResponseEntity.ok("{\"code\":\"OK\",\"data\":{\"private\":\"secret\"}}".getBytes()));mvc.perform(get(path).cookie(new Cookie("AISTOCK_SESSION","a"))).andExpect(status().isServiceUnavailable()).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("secret"))));}
}
